package com.alradhy.discoverylab;

import java.util.SortedSet;
import java.util.TreeSet;

/** One plotted series, generated by evaluating the lab's actual readout model. */
public final class GraphSweep {
    private GraphSweep() {}

    public static final class Series {
        public final double[] x;
        public final double[] y;
        public final double markerX;
        public final double markerY;

        private Series(double[] x, double[] y, double markerX, double markerY) {
            this.x = x;
            this.y = y;
            this.markerX = markerX;
            this.markerY = markerY;
        }
    }

    public static Series sample(double min, double max, double discreteStep, int axis,
                                 double[] configuration, double[] breakpoints, ExpansionModels.Model model) {
        SortedSet<Double> domain = new TreeSet<>();
        int intervals = discreteStep > 0 ? (int) Math.round((max - min) / discreteStep) : 160;
        for (int i = 0; i <= intervals; i++) {
            domain.add(i == intervals ? max : min + i * (discreteStep > 0 ? discreteStep : (max - min) / intervals));
        }
        double markerX = configuration[axis];
        domain.add(markerX);
        for (double point : breakpoints) {
            if (point > min && point < max) domain.add(point);
        }
        double[] xs = new double[domain.size()];
        double[] ys = new double[domain.size()];
        double[] probe = configuration.clone();
        int index = 0;
        for (double x : domain) {
            probe[axis] = x;
            xs[index] = x;
            ys[index] = model.measure(probe);
            index++;
        }
        return new Series(xs, ys, markerX, model.measure(configuration));
    }
}
